import functools

def my_decorator(func):
    # 1. @wraps를 쓰지 않으면?
    # wrapper.__name__ = "wrapper"가 됨

    @functools.wraps(func) # 2. 원본 함수의 메타데이터 복사
    def wrapper(*args, **kwargs):
        """This is the wrapper function"""
        print("Call Decorator")
        return func(*args, **kwargs)
    return wrapper

@my_decorator
def add(a, b):
    """두 수를 더하는 함수입니다."""
    return a + b

def example():
    print(f"Function Name: {add.__name__}")
    print(f"Docstring: {add.__doc__}")

    # 만약 @wraps가 없다면 Name은 'wrapper', Docstring은 wrapper의 것이 출력됨
    print(f"Result: {add(10, 20)}")

if __name__ == '__main__':
    example()
